  {dialogo&&conversa&&<Dialog open onOpenChange={aberto=>{if(!aberto&&!ocupado)setDialogo(null);}}><DialogContent className={dialogo==='modelo'?'modal modal-template':'modal'} showCloseButton={false}><DialogTitle>{dialogo==='transferir'?'Transferir atendimento':dialogo==='nota'?'Nota interna':dialogo==='etiquetas'?'Etiquetas':'Enviar template'}</DialogTitle><DialogDescription>As alterações são conferidas e gravadas no servidor. {conversa.ficticia?'Esta conversa é isolada para testes.':'Este atendimento exige sua permissão atual.'}</DialogDescription><DialogClose className="close-icon" aria-label="Fechar diálogo" disabled={ocupado}><X size={20}/></DialogClose>{dialogo==='transferir'?<><label htmlFor="responsavel-transferencia">Responsável<Escolha id="responsavel-transferencia" label="Responsável" value={responsavel||'__sem__'} options={[{valor:'__sem__',rotulo:'Escolha um responsável'},...equipe.usuarios.map(u=>({valor:u.id,rotulo:u.nome}))]} onChange={id=>setResponsavel(id==='__sem__'?'':id)}/></label><label htmlFor="equipe-transferencia">Equipe<Escolha id="equipe-transferencia" label="Equipe" value={equipeId||'__sem__'} options={[{valor:'__sem__',rotulo:'Não atribuída'},...equipe.equipes.map(u=>({valor:u.id,rotulo:u.nome}))]} onChange={id=>setEquipeId(id==='__sem__'?'':id)}/></label></>:dialogo==='modelo'?<EnvioTemplateOperacao modelos={modelos} selecionado={modelo} selecionar={id=>{setModelo(id);setVariaveis({});}} variaveis={variaveis} alterar={setVariaveis} carregando={carregandoModelos} ocupado={ocupado}/>:<label>{dialogo==='nota'?'Texto da nota':'Etiquetas separadas por vírgula'}<textarea className="field" maxLength={dialogo==='nota'?2000:1858} value={textoAcao} onChange={e=>setTextoAcao(limparTextoOperacao(e.target.value,dialogo==='nota'?2000:1858))}/></label>}{dialogo==='etiquetas'&&<p className="muted">Até 30 etiquetas, com 60 caracteres cada. Todas as etiquetas válidas são preservadas ao salvar.</p>}{erro&&<p role="alert">{erro}</p>}<div className="toolbar"><DialogClose data-acao="cancelar" className="btn" disabled={ocupado}>Cancelar</DialogClose><button className="btn primary" disabled={ocupado||(dialogo==='nota'&&!permite('notas.adicionar'))||(dialogo==='etiquetas'&&!permite('etiquetas.editar'))||(dialogo==='transferir'&&!permiteAtender)||(dialogo==='transferir'&&!responsavel)||(dialogo==='nota'&&!textoAcao.trim())||(dialogo==='etiquetas'&&(etiquetasAcao.length>30||etiquetasAcao.some(t=>t.length>60)))||(dialogo==='modelo'&&(!podeEscrever||incerto||!modelo||modeloAtual?.variaveis.some(v=>!variaveis[v]?.trim())))} onClick={e=>dialogo==='modelo'?void enviar(e,'template'):void executarAcao(dialogo==='transferir'?{acao:'transferir',responsavelId:responsavel||null,equipeId:equipeId||null}:dialogo==='nota'?{acao:'nota',texto:textoAcao}:{acao:'etiquetas',tags:etiquetasAcao})}><Check size={16}/>{dialogo==='modelo'?'Enviar template':'Salvar'}</button></div></DialogContent></Dialog>}
